{"path": "/tmp/sv-cb473b7e324b404ba66d633fca487901/Components/Pages/Settings/ProfileSection.razor", "file_text": "@namespace sv_cb473b7e324b404ba66d633fca487901.Components.Pages.Settings
@using sv_cb473b7e324b404ba66d633fca487901.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <div class="avatar-image">
                    @if (!string.IsNullOrEmpty(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <span class="avatar-url">@_avatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_bio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }
}
"}

{"path": "/tmp/sv-cb473b7e324b404ba66d633fca487901/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_cb473b7e324b404ba66d633fca487901.Components.Pages.Settings
@using sv_cb473b7e324b404ba66d633fca487901.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_loading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-switch"></span>
                    <span>Email Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-switch"></span>
                    <span>Push Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-switch"></span>
                    <span>Weekly Digest</span>
                </label>
            </div>

            @if (_channels.Count > 0)
            {
                <div class="channels-section">
                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in _channels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@_mutedChannels.Contains(channel)"
                                       @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                                <span>@channel</span>
                            </label>
                        }
                    </div>
                </div>
            }

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync">Save Preferences</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _channels = [];
    private HashSet<string> _mutedChannels = [];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = [.. prefs.MutedChannels];
        _channels = [.. prefs.MutedChannels, "general", "announcements", "random", "dev", "design"];
        _channels = _channels.Distinct().ToList();
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-cb473b7e324b404ba66d633fca487901/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "@namespace sv_cb473b7e324b404ba66d633fca487901.Components.Pages.Settings
@using sv_cb473b7e324b404ba66d633fca487901.Services
@inject ISettingsService SettingsService

<div class="expandable-panel">
    <button class="panel-header" @onclick="() => _expanded = !_expanded">
        <span>Change Password</span>
        <span class="expand-icon">@(_expanded ? "▼" : "▶")</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="toast error">@_error</div>
            }
            @if (_showSuccess)
            {
                <div class="toast success">Password updated successfully!</div>
            }

            <button class="btn-primary" @onclick="UpdatePasswordAsync" disabled="@_updating">
                @(_updating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private bool _updating;
    private bool _showSuccess;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _error = "";

    private async Task UpdatePasswordAsync()
    {
        _error = "";
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _updating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _ = HideToastAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _updating = false;
        }
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-cb473b7e324b404ba66d633fca487901/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@namespace sv_cb473b7e324b404ba66d633fca487901.Components.Pages.Settings
@using sv_cb473b7e324b404ba66d633fca487901.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is { Count: > 0 })
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
    else
    {
        <p>No active sessions.</p>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="confirm-dialog-overlay">
            <div class="confirm-dialog">
                <p>Revoke session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="dialog-actions">
                    <button class="btn-danger" @onclick="RevokeConfirmedAsync">Confirm Revoke</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task RevokeConfirmedAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-cb473b7e324b404ba66d633fca487901/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_cb473b7e324b404ba66d633fca487901.Components.Pages.Settings
@using sv_cb473b7e324b404ba66d633fca487901.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="two-factor-row">
                <label class="toggle-item">
                    <input type="checkbox" checked="@_twoFactorEnabled" disabled />
                    <span class="toggle-switch"></span>
                    <span>Two-Factor Authentication</span>
                </label>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnRevoke="RevokeSessionAsync" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private string? _currentSessionId;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // Assume the first session is the current one
        _currentSessionId = _sessions.FirstOrDefault()?.Id;
        _loading = false;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}
"}

