+    background: #f8f9fa;
+    border: none;
+    border-radius: 8px;
+    cursor: pointer;
+    font-size: 0.95rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* Two-factor */
+.two-factor-section {
+    margin: 1.5rem 0;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 8px;
+}
+
+.two-factor-row {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.status-indicator {
+    font-size: 0.85rem;
+    font-weight: 600;
+    padding: 0.2rem 0.6rem;
+    border-radius: 4px;
+}
+
+.status-indicator.enabled {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.status-indicator.disabled {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.info-text {
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.5rem;
+}
+
+/* Sessions table */
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    background: #cfe2ff;
+    color: #084298;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+}
+
+/* Confirmation dialog */
+.confirm-dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.4);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.confirm-dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 10px;
+    max-width: 400px;
+    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1rem;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+.radio-item input[type="radio"] {
+    accent-color: #0d6efd;
+}
+
+/* Live preview */
+.live-preview {
+    margin: 1.5rem 0;
+    transition: all 0.3s ease;
+}
+
+.live-preview h4 {
+    margin-top: 0;
+    margin-bottom: 0.5rem;
+}
+
+.live-preview p {
+    margin: 0.25rem 0;
+}
+
+/* Loading */
+.loading {
+    color: #666;
+    font-style: italic;
+}
+

